<template>
    <h2>GS리테일 Work List</h2>

    <!-- 필터 -->
    <div class="filter-box">
        <input
            v-model="searchKeyword"
            type="text"
            placeholder="검색"
        />

        <select v-model="statusFilter">
            <option value="">전체</option>
            <option value="COM">완료</option>
            <option value="ING">진행중</option>
        </select>
    </div>

    <table>
        <thead>
            <tr>
                <th>1Depth</th>
                <th>2Depth</th>
                <th>3Depth</th>
                <th>4Depth</th>
                <th>5Depth</th>
                <th>6Depth</th>
                <th>Type</th>
                <th>ID</th>
                <th>시작일</th>
                <th>종료일</th>
                <th>상태</th>
                <th>비고</th>
            </tr>
        </thead>

        <tbody>
            <tr v-for="(item, index) in filteredList" :key="index">
                <td>{{ item.depth1 }}</td>
                <td>{{ item.depth2 }}</td>
                <td>{{ item.depth3 }}</td>
                <td>{{ item.depth4 }}</td>
                <td>{{ item.depth5 }}</td>
                <td>{{ item.depth6 }}</td>
                <td>{{ item.type }}</td>
                <td>
                    <a :href="item.path">{{ item.id }}</a>
                </td>
                <td>{{ item.startDate }}</td>
                <td>{{ item.endDate }}</td>
                <td :class="item.status">{{ item.status }}</td>
                <td>{{ item.note }}</td>
            </tr>
        </tbody>
    </table>
</template>

<script>
import data from "@/assets/language/menu/workList.json"

export default {
    data() {
        return {
            workList: data,
            searchKeyword: "",
            statusFilter: ""
        }
    },

    async created() {
        const res = await fetch("/assets/language/menu/workList.json")
        this.workList = await res.json()
    },

    computed: {
        filteredList() {
            return this.workList.filter(item => {
                const keywordMatch =
                    !this.searchKeyword ||
                    Object.values(item).some(v =>
                        String(v).toLowerCase().includes(this.searchKeyword.toLowerCase())
                    )

                const statusMatch =
                    !this.statusFilter || item.status === this.statusFilter

                return keywordMatch && statusMatch
            })
        }
    }
}
</script>

<style scoped>
h2 {
    font-size: 2rem;
    text-align: center;
}

.filter-box {
    margin-bottom: 16px;
    display: flex;
    gap: 10px;
}

input, select {
    padding: 6px 10px;
}

table {
    width: 100%;
    border-collapse: collapse;
}

th, td {
    border: 1px solid #ccc;
    padding: 8px;
}

/* 상태 스타일 */
.COM {
    color: green;
    font-weight: bold;
}

.ING {
    color: orange;
    font-weight: bold;
}
</style>